#include <bits/stdc++.h>
using namespace std;

#define rep(i, n) for(int i = 0; i < n; ++i)
#define N 1000

int n,m,x,y;
vector<int>e[N];
vector<int>ans;
bool used[N];
bool cand[N];

void dfs(int k){
	cand[k]=true;
	int sz=e[k].size();
	rep(i,sz){
		if((!cand[e[k][i]])&&(!used[e[k][i]]))dfs(e[k][i]);
	}
	return;
}

void solve(void){
	ans.clear();
	int cur = x;
	while(cur!=y){
		ans.push_back(cur);
		used[cur]=true;
		rep(i,n)cand[i]=false;
		dfs(y);
		int sz=e[cur].size();
		int nxt=n;
		rep(i,sz)if(cand[e[cur][i]])nxt=min(nxt,e[cur][i]);
		cur=nxt;	
	}
	ans.push_back(y);
	return;
}


int main(void){
	int t;
	cin >> t;
	rep(_,t){
		cin >> n >> m >> x >> y;
		x--,y--;
		rep(i,n)used[i]=false;
		int u,v;
		rep(i,m){
			cin >> u >> v;
			e[u-1].push_back(v-1);
			e[v-1].push_back(u-1);
		}
		solve();
		int sz = ans.size();
		rep(i,sz-1)cout << (ans[i]+1) << " ";
		cout << (ans[sz-1]+1) << endl;
		rep(i,n)e[i].clear();
	}
	return 0;
}
